window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-905330d836bc8963"]={"versions": [{"id": "FIG-905330d836bc8963", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentendiagramm (Abhängigkeits- und Schnittstellenmodellierung der AUTOSAR Adaptive Platform nach <em>AUTOSAR_EXP_SWArchitecture</em>).\n</li><li><strong>Architektur-Kontext:</strong> Spezifiziert die Systemintegration und die erforderlichen Schnittstellen (<em>Required Interfaces</em>) des Functional Clusters <code>Firewall</code>. Es definiert die bidirektionale Rolle der Firewall im Adaptive-System: Einerseits als filternde Kontrollinstanz auf Systemebene über dem OS-Netzwerk-Stack, andererseits als Security-Sensor, der Angriffs- und Anomalieereignisse an das fahrzeuginterne Intrusion Detection System (IdsM) meldet.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Functional Clusters:</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Firewall (daemon-based)</code>: Client- und Steuerungskomponente; als nativer OS-Daemon realisierter Functional Cluster zur Filterung des IP-basierten Datenverkehrs (Paketfilterung, Zustandsprüfung, Routing-Kontrolle).\n</li><li><code>«aapFunctionalCluster» Adaptive Intrusion Detection System Manager (daemon-based)</code>: IdsM-Instanz; eigenständiger Daemon zur Erfassung, Pufferung, Filterung und Weiterleitung sicherheitsrelevanter Vorfälle (Security Events / Qualified Security Events).\n</li><li><code>Operating System</code>: POSIX-konformes Plattform-Betriebssystem (z. B. Linux/QNX), das die Basistreiber und den nativen Netzwerk-Stack kapselt.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«aapPortInterface,aapAPI» EventReporter</code>: Standardisierte funktionale Plattform-Schnittstelle (ARA-konforme C++-API).\n<ul class=\"fig-list\"><li>Operation: <code>+ ReportEvent()</code> zur standardisierten Übergabe von Security Events an den IdsM.\n</li></ul>\n</li><li><code>«aapInternal» TCP/IP Stack</code>: Plattform-interne, nicht über das Adaptive Service Interface standardisierte Low-Level-Schnittstelle zum OS-Netzwerkstack (z. B. Kernel-Hooks, Netfilter/nftables, eBPF, Socket-Filter).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>EventReporter</code>: Die Firewall konsumiert die Reporterschnittstelle (Client-Rolle).\n</li><li><code>Adaptive Intrusion Detection System Manager</code> $\\xleftarrow{\\text{realizes}}$ <code>EventReporter</code>: Der IdsM implementiert und exponiert diese Schnittstelle.\n</li><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>TCP/IP Stack</code>: Die Firewall bindet sich direkt an die Paketverarbeitung des Betriebssystems an.\n</li><li><code>Operating System</code> $\\xleftarrow{\\text{realizes}}$ <code>TCP/IP Stack</code>: Das Betriebssystem stellt den Netzwerk-Stack bereit.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Paket-Interzeption &amp; Regelauswertung (Synchron/OS-Ebene):</strong>\n<ul class=\"fig-list\"><li>Eingehende/ausgehende IP-Pakete durchlaufen den <code>TCP/IP Stack</code> des <code>Operating System</code>.\n</li><li>Die <code>Firewall</code> greift über die <code>«aapInternal»</code>-Schnittstelle in den Paketfluss ein und bewertet Pakete gegen hinterlegte Regelsätze (Stateful Packet Inspection, Black-/Whitelisting, Rate-Limiting).\n</li></ul>\n</li><li><strong>Entscheidungs- und Filterpfad:</strong>\n<ul class=\"fig-list\"><li>Valide Pakete passieren den Stack transparent.\n</li><li>Illegitime Pakete werden verworfen (Drop), abgewiesen (Reject) oder markiert.\n</li></ul>\n</li><li><strong>Security Event Trigger:</strong>\n<ul class=\"fig-list\"><li>Bei Regelverletzungen (z. B. Portscan-Erkennung, Payload-Anomalie, IP-Spoofing, DoS-Muster) generiert die Firewall einen Security-Incident.\n</li></ul>\n</li><li><strong>Ereignismeldung (<code>ReportEvent()</code>):</strong>\n<ul class=\"fig-list\"><li>Die <code>Firewall</code> ruft <code>EventReporter::ReportEvent(...)</code> auf dem IdsM auf.\n</li><li>Übergabe von Security Event ID, Timestamp und kontextspezifischen Daten (z. B. Quell-/Ziel-IP, Port, Protocol, Drop-Reason).\n</li></ul>\n</li><li><strong>IdsM-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Adaptive Intrusion Detection System Manager</code> verarbeitet das Event asynchron weiter (Aggregation, Schwellwertanalyse, Logging oder Alarmierung via Telematik/SOC).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li>Da die Firewall als <code>daemon-based</code> deklariert ist, muss sie im Manifest des Execution Management (<code>ara::exec</code>) als eigener Prozess mit entsprechenden POSIX-Capabilities (<code>CAP_NET_ADMIN</code>, <code>CAP_NET_RAW</code> unter Linux) und dedizierten Start-/Shutdown-Abhängigkeiten konfiguriert werden.\n</li></ul>\n</li><li><strong>Portabilitäts-Einschränkung (<code>«aapInternal»</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kopplung an den <code>TCP/IP Stack</code> erfolgt proprietär/OS-spezifisch. Bei Plattform-Migrationen (z. B. Linux ↔ QNX) ist die Firewall-Engine bzw. der Binding-Layer neu zu implementieren, da hier kein standardisiertes <code>ara::com</code>-Service-Interface vorliegt.\n</li></ul>\n</li><li><strong>IdsM-API-Vertrag (<code>ReportEvent</code>):</strong>\n<ul class=\"fig-list\"><li>Aufrufkonventionen und Pufferverhalten müssen latenzarm ausgelegt sein. Blockierende Aufrufe in <code>ReportEvent()</code> dürfen den Durchsatz des OS-Netzwerk-Stacks unter Last nicht drosseln (nicht-blockierende Ringpuffer oder asynchrone Dispatch-Mechanismen zwingend erforderlich).\n</li><li>Die von der Firewall gemeldeten Events müssen den in der Security-Extract-Konfiguration (<code>AUTOSAR_SWS_IntrusionDetectionSystemManager</code>) definierten <code>EventDefinitionId</code>s exakt entsprechen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-fce928ed410bb213", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentendiagramm (Abhängigkeits- und Schnittstellenmodellierung der AUTOSAR Adaptive Platform nach <em>AUTOSAR_EXP_SWArchitecture</em>).\n</li><li><strong>Architektur-Kontext:</strong> Spezifiziert die Systemintegration und die erforderlichen Schnittstellen (<em>Required Interfaces</em>) des Functional Clusters <code>Firewall</code>. Es definiert die bidirektionale Rolle der Firewall im Adaptive-System: Einerseits als filternde Kontrollinstanz auf Systemebene über dem OS-Netzwerk-Stack, andererseits als Security-Sensor, der Angriffs- und Anomalieereignisse an das fahrzeuginterne Intrusion Detection System (IdsM) meldet.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Functional Clusters:</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Firewall (daemon-based)</code>: Client- und Steuerungskomponente; als nativer OS-Daemon realisierter Functional Cluster zur Filterung des IP-basierten Datenverkehrs (Paketfilterung, Zustandsprüfung, Routing-Kontrolle).\n</li><li><code>«aapFunctionalCluster» Intrusion Detection System Manager (daemon-based)</code>: IdsM-Instanz; eigenständiger Daemon zur Erfassung, Pufferung, Filterung und Weiterleitung sicherheitsrelevanter Vorfälle (Security Events / Qualified Security Events).\n</li><li><code>Operating System</code>: POSIX-konformes Plattform-Betriebssystem (z. B. Linux/QNX), das die Basistreiber und den nativen Netzwerk-Stack kapselt.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«aapPortInterface,aapAPI» EventReporter</code>: Standardisierte funktionale Plattform-Schnittstelle (ARA-konforme C++-API).\n<ul class=\"fig-list\"><li>Operation: <code>+ ReportEvent()</code> zur standardisierten Übergabe von Security Events an den IdsM.\n</li></ul>\n</li><li><code>«aapInternal» TCP/IP Stack</code>: Plattform-interne, nicht über das Adaptive Service Interface standardisierte Low-Level-Schnittstelle zum OS-Netzwerkstack (z. B. Kernel-Hooks, Netfilter/nftables, eBPF, Socket-Filter).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>EventReporter</code>: Die Firewall konsumiert die Reporterschnittstelle (Client-Rolle).\n</li><li><code>Intrusion Detection System Manager</code> $\\xleftarrow{\\text{realizes}}$ <code>EventReporter</code>: Der IdsM implementiert und exponiert diese Schnittstelle.\n</li><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>TCP/IP Stack</code>: Die Firewall bindet sich direkt an die Paketverarbeitung des Betriebssystems an.\n</li><li><code>Operating System</code> $\\xleftarrow{\\text{realizes}}$ <code>TCP/IP Stack</code>: Das Betriebssystem stellt den Netzwerk-Stack bereit.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Paket-Interzeption &amp; Regelauswertung (Synchron/OS-Ebene):</strong>\n<ul class=\"fig-list\"><li>Eingehende/ausgehende IP-Pakete durchlaufen den <code>TCP/IP Stack</code> des <code>Operating System</code>.\n</li><li>Die <code>Firewall</code> greift über die <code>«aapInternal»</code>-Schnittstelle in den Paketfluss ein und bewertet Pakete gegen hinterlegte Regelsätze (Stateful Packet Inspection, Black-/Whitelisting, Rate-Limiting).\n</li></ul>\n</li><li><strong>Entscheidungs- und Filterpfad:</strong>\n<ul class=\"fig-list\"><li>Valide Pakete passieren den Stack transparent.\n</li><li>Illegitime Pakete werden verworfen (Drop), abgewiesen (Reject) oder markiert.\n</li></ul>\n</li><li><strong>Security Event Trigger:</strong>\n<ul class=\"fig-list\"><li>Bei Regelverletzungen (z. B. Portscan-Erkennung, Payload-Anomalie, IP-Spoofing, DoS-Muster) generiert die Firewall einen Security-Incident.\n</li></ul>\n</li><li><strong>Ereignismeldung (<code>ReportEvent()</code>):</strong>\n<ul class=\"fig-list\"><li>Die <code>Firewall</code> ruft <code>EventReporter::ReportEvent(...)</code> auf dem IdsM auf.\n</li><li>Übergabe von Security Event ID, Timestamp und kontextspezifischen Daten (z. B. Quell-/Ziel-IP, Port, Protocol, Drop-Reason).\n</li></ul>\n</li><li><strong>IdsM-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Adaptive Intrusion Detection System Manager</code> verarbeitet das Event asynchron weiter (Aggregation, Schwellwertanalyse, Logging oder Alarmierung via Telematik/SOC).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li>Da die Firewall als <code>daemon-based</code> deklariert ist, muss sie im Manifest des Execution Management (<code>ara::exec</code>) als eigener Prozess mit entsprechenden POSIX-Capabilities (<code>CAP_NET_ADMIN</code>, <code>CAP_NET_RAW</code> unter Linux) und dedizierten Start-/Shutdown-Abhängigkeiten konfiguriert werden.\n</li></ul>\n</li><li><strong>Portabilitäts-Einschränkung (<code>«aapInternal»</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kopplung an den <code>TCP/IP Stack</code> erfolgt proprietär/OS-spezifisch. Bei Plattform-Migrationen (z. B. Linux ↔ QNX) ist die Firewall-Engine bzw. der Binding-Layer neu zu implementieren, da hier kein standardisiertes <code>ara::com</code>-Service-Interface vorliegt.\n</li></ul>\n</li><li><strong>IdsM-API-Vertrag (<code>ReportEvent</code>):</strong>\n<ul class=\"fig-list\"><li>Aufrufkonventionen und Pufferverhalten müssen latenzarm ausgelegt sein. Blockierende Aufrufe in <code>ReportEvent()</code> dürfen den Durchsatz des OS-Netzwerk-Stacks unter Last nicht drosseln (nicht-blockierende Ringpuffer oder asynchrone Dispatch-Mechanismen zwingend erforderlich).\n</li><li>Die von der Firewall gemeldeten Events müssen den in der Security-Extract-Konfiguration (<code>AUTOSAR_SWS_IntrusionDetectionSystemManager</code>) definierten <code>EventDefinitionId</code>s exakt entsprechen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-32bda29d3b576cb0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentendiagramm (Abhängigkeits- und Schnittstellenmodellierung der AUTOSAR Adaptive Platform nach <em>AUTOSAR_EXP_SWArchitecture</em>).\n</li><li><strong>Architektur-Kontext:</strong> Spezifiziert die Systemintegration und die erforderlichen Schnittstellen (<em>Required Interfaces</em>) des Functional Clusters <code>Firewall</code>. Es definiert die bidirektionale Rolle der Firewall im Adaptive-System: Einerseits als filternde Kontrollinstanz auf Systemebene über dem OS-Netzwerk-Stack, andererseits als Security-Sensor, der Angriffs- und Anomalieereignisse an das fahrzeuginterne Intrusion Detection System (IdsM) meldet.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Functional Clusters:</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Firewall (daemon-based)</code>: Client- und Steuerungskomponente; als nativer OS-Daemon realisierter Functional Cluster zur Filterung des IP-basierten Datenverkehrs (Paketfilterung, Zustandsprüfung, Routing-Kontrolle).\n</li><li><code>«aapFunctionalCluster» Intrusion Detection System Manager (daemon-based)</code>: IdsM-Instanz; eigenständiger Daemon zur Erfassung, Pufferung, Filterung und Weiterleitung sicherheitsrelevanter Vorfälle (Security Events / Qualified Security Events).\n</li><li><code>Operating System</code>: POSIX-konformes Plattform-Betriebssystem (z. B. Linux/QNX), das die Basistreiber und den nativen Netzwerk-Stack kapselt.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«aapPortInterface,aapAPI» EventReporter</code>: Standardisierte funktionale Plattform-Schnittstelle (ARA-konforme C++-API).\n<ul class=\"fig-list\"><li>Operation: <code>+ ReportEvent()</code> zur standardisierten Übergabe von Security Events an den IdsM.\n</li></ul>\n</li><li><code>«aapInternal» TCP/IP Stack</code>: Plattform-interne, nicht über das Adaptive Service Interface standardisierte Low-Level-Schnittstelle zum OS-Netzwerkstack (z. B. Kernel-Hooks, Netfilter/nftables, eBPF, Socket-Filter).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>EventReporter</code>: Die Firewall konsumiert die Reporterschnittstelle (Client-Rolle).\n</li><li><code>Intrusion Detection System Manager</code> $\\xleftarrow{\\text{realizes}}$ <code>EventReporter</code>: Der IdsM implementiert und exponiert diese Schnittstelle.\n</li><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>TCP/IP Stack</code>: Die Firewall bindet sich direkt an die Paketverarbeitung des Betriebssystems an.\n</li><li><code>Operating System</code> $\\xleftarrow{\\text{realizes}}$ <code>TCP/IP Stack</code>: Das Betriebssystem stellt den Netzwerk-Stack bereit.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Paket-Interzeption &amp; Regelauswertung (Synchron/OS-Ebene):</strong>\n<ul class=\"fig-list\"><li>Eingehende/ausgehende IP-Pakete durchlaufen den <code>TCP/IP Stack</code> des <code>Operating System</code>.\n</li><li>Die <code>Firewall</code> greift über die <code>«aapInternal»</code>-Schnittstelle in den Paketfluss ein und bewertet Pakete gegen hinterlegte Regelsätze (Stateful Packet Inspection, Black-/Whitelisting, Rate-Limiting).\n</li></ul>\n</li><li><strong>Entscheidungs- und Filterpfad:</strong>\n<ul class=\"fig-list\"><li>Valide Pakete passieren den Stack transparent.\n</li><li>Illegitime Pakete werden verworfen (Drop), abgewiesen (Reject) oder markiert.\n</li></ul>\n</li><li><strong>Security Event Trigger:</strong>\n<ul class=\"fig-list\"><li>Bei Regelverletzungen (z. B. Portscan-Erkennung, Payload-Anomalie, IP-Spoofing, DoS-Muster) generiert die Firewall einen Security-Incident.\n</li></ul>\n</li><li><strong>Ereignismeldung (<code>ReportEvent()</code>):</strong>\n<ul class=\"fig-list\"><li>Die <code>Firewall</code> ruft <code>EventReporter::ReportEvent(...)</code> auf dem IdsM auf.\n</li><li>Übergabe von Security Event ID, Timestamp und kontextspezifischen Daten (z. B. Quell-/Ziel-IP, Port, Protocol, Drop-Reason).\n</li></ul>\n</li><li><strong>IdsM-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Adaptive Intrusion Detection System Manager</code> verarbeitet das Event asynchron weiter (Aggregation, Schwellwertanalyse, Logging oder Alarmierung via Telematik/SOC).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li>Da die Firewall als <code>daemon-based</code> deklariert ist, muss sie im Manifest des Execution Management (<code>ara::exec</code>) als eigener Prozess mit entsprechenden POSIX-Capabilities (<code>CAP_NET_ADMIN</code>, <code>CAP_NET_RAW</code> unter Linux) und dedizierten Start-/Shutdown-Abhängigkeiten konfiguriert werden.\n</li></ul>\n</li><li><strong>Portabilitäts-Einschränkung (<code>«aapInternal»</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kopplung an den <code>TCP/IP Stack</code> erfolgt proprietär/OS-spezifisch. Bei Plattform-Migrationen (z. B. Linux ↔ QNX) ist die Firewall-Engine bzw. der Binding-Layer neu zu implementieren, da hier kein standardisiertes <code>ara::com</code>-Service-Interface vorliegt.\n</li></ul>\n</li><li><strong>IdsM-API-Vertrag (<code>ReportEvent</code>):</strong>\n<ul class=\"fig-list\"><li>Aufrufkonventionen und Pufferverhalten müssen latenzarm ausgelegt sein. Blockierende Aufrufe in <code>ReportEvent()</code> dürfen den Durchsatz des OS-Netzwerk-Stacks unter Last nicht drosseln (nicht-blockierende Ringpuffer oder asynchrone Dispatch-Mechanismen zwingend erforderlich).\n</li><li>Die von der Firewall gemeldeten Events müssen den in der Security-Extract-Konfiguration (<code>AUTOSAR_SWS_IntrusionDetectionSystemManager</code>) definierten <code>EventDefinitionId</code>s exakt entsprechen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-237713263eec7842", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentendiagramm (Abhängigkeits- und Schnittstellenmodellierung der AUTOSAR Adaptive Platform nach <em>AUTOSAR_EXP_SWArchitecture</em>).\n</li><li><strong>Architektur-Kontext:</strong> Spezifiziert die Systemintegration und die erforderlichen Schnittstellen (<em>Required Interfaces</em>) des Functional Clusters <code>Firewall</code>. Neben der bidirektionalen Security-Rolle – Paketfilterung auf Betriebssystemebene (<code>TCP/IP Stack</code>) und Incident-Reporting an das fahrzeuginterne Intrusion Detection System (<code>Intrusion Detection System Manager</code>) – integriert das Diagramm die Firewall nun explizit in das Plattform-Lebenszyklusmanagement: Die Firewall nutzt den <code>ExecutionClient</code>, um ihren Ausführungszustand normgerecht an das <code>Execution Management</code> zu melden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Functional Clusters:</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Firewall (daemon-based)</code>: Client- und Steuerungskomponente; als nativer OS-Daemon realisierter Functional Cluster zur Filterung des IP-basierten Datenverkehrs (Paketfilterung, Zustandsprüfung, Routing-Kontrolle).\n</li><li><code>«aapFunctionalCluster» Intrusion Detection System Manager (daemon-based)</code>: IdsM-Instanz; eigenständiger Daemon zur Erfassung, Pufferung, Filterung und Weiterleitung sicherheitsrelevanter Vorfälle (Security Events / Qualified Security Events).\n</li><li><code>«aapFunctionalCluster» Execution Management (daemon-based)</code>: Zentraler Plattform-Daemon für Prozessverwaltung, Zustandsmanagement (State Management), Prozessüberwachung und Lebenszyklussteuerung.\n</li><li><code>Operating System</code>: POSIX-konformes Plattform-Betriebssystem (z. B. Linux/QNX), das die Basistreiber und den nativen Netzwerk-Stack kapselt.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><code>«aapPortInterface,aapAPI» EventReporter</code>: Standardisierte funktionale Plattform-Schnittstelle (ARA-konforme C++-API).\n<ul class=\"fig-list\"><li>Operation: <code>+ ReportEvent()</code> zur standardisierten Übergabe von Security Events an den IdsM.\n</li></ul>\n</li><li><code>«aapAPI,aapNativeInterface» ExecutionClient</code>: Native C++-Bibliotheksschnittstelle für Applikationen und Daemons zur Interaktion mit dem Execution Management.\n<ul class=\"fig-list\"><li>Operation: <code>+ Create()</code> (statische Factory-Methode zur Erzeugung der Client-Instanz).\n</li><li>Operation: <code>+ ReportExecutionState(ExecutionState)</code> zur Übermittlung des aktuellen Prozesszustands (z. B. <code>kRunning</code>, <code>kTerminating</code>).\n</li></ul>\n</li><li><code>«aapInternal» TCP/IP Stack</code>: Plattform-interne Low-Level-Schnittstelle zum OS-Netzwerkstack (z. B. Kernel-Hooks, Netfilter/nftables, eBPF, Socket-Filter).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>EventReporter</code>: Die Firewall konsumiert die Reporterschnittstelle (Client-Rolle).\n</li><li><code>Intrusion Detection System Manager</code> $\\xleftarrow{\\text{realizes}}$ <code>EventReporter</code>: Der IdsM implementiert und exponiert die Schnittstelle.\n</li><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>ExecutionClient</code>: Die Firewall nutzt den ExecutionClient zur Lebenszyklus- und Zustandssynchronisation.\n</li><li><code>Execution Management</code> $\\xleftarrow{\\text{realizes}}$ <code>ExecutionClient</code>: Execution Management realisiert das Backend für die ExecutionClient-API.\n</li><li><code>Firewall</code> $\\xrightarrow{\\text{«use»}}$ <code>TCP/IP Stack</code>: Die Firewall bindet sich direkt an die Paketverarbeitung des Betriebssystems an.\n</li><li><code>Operating System</code> $\\xleftarrow{\\text{realizes}}$ <code>TCP/IP Stack</code>: Das Betriebssystem stellt den Netzwerk-Stack bereit.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Prozessstart &amp; Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Das <code>Execution Management</code> startet den <code>Firewall</code>-Daemon gemäß Bereitstellungs- und Startup-Konfiguration.\n</li><li>Die Firewall instanziiert die Client-Schnittstelle über <code>ExecutionClient::Create()</code>.\n</li></ul>\n</li><li><strong>Zustandsmeldung (<code>kRunning</code>):</strong>\n<ul class=\"fig-list\"><li>Sobald die interne Initialisierung, Regelladung und das OS-Binding abgeschlossen sind, meldet die Firewall ihre Einsatzbereitschaft via <code>ExecutionClient::ReportExecutionState(ExecutionState::kRunning)</code> an das <code>Execution Management</code>.\n</li></ul>\n</li><li><strong>Paket-Interzeption &amp; Regelauswertung (OS-Ebene):</strong>\n<ul class=\"fig-list\"><li>Eingehende und ausgehende IP-Pakete passieren den <code>TCP/IP Stack</code> des <code>Operating System</code>.\n</li><li>Die <code>Firewall</code> greift über die <code>«aapInternal»</code>-Schnittstelle synchron in den Datenfluss ein und prüft Pakete anhand hinterlegter Filtersätze (Stateful Inspection, Whitelisting, Drop/Reject).\n</li></ul>\n</li><li><strong>Security Event Trigger &amp; Meldung (<code>ReportEvent()</code>):</strong>\n<ul class=\"fig-list\"><li>Bei sicherheitsrelevanten Anomalien oder Regelverletzungen (z. B. Portscans, SYN-Floods, unautorisierte Verbindungsversuche) generiert die Firewall einen Security-Incident.\n</li><li>Aufruf von <code>EventReporter::ReportEvent(...)</code> am <code>Intrusion Detection System Manager</code> unter Übergabe von Event-ID, Zeitstempel und Kontextdaten.\n</li></ul>\n</li><li><strong>IdsM-Verarbeitung:</strong>\n<ul class=\"fig-list\"><li>Der IdsM empfängt das Event, filtert, puffert und aggregiert es und verarbeitet es gemäß IDS-Sicherheitsstrategie.\n</li></ul>\n</li><li><strong>Terminierung &amp; Shutdown:</strong>\n<ul class=\"fig-list\"><li>Bei einem Plattform-Zustandswechsel oder Shutdown-Signal meldet die Firewall ihren Beendigungszustand via <code>ReportExecutionState(...)</code> an das <code>Execution Management</code>, bevor Ressourcen und Hooks freigegeben werden.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Verbindliche Prozesssynchronisation (<code>ExecutionClient</code>):</strong>\n<ul class=\"fig-list\"><li>Durch die explizite Modellierung des <code>ExecutionClient</code> unterliegt die Firewall normativ den Vorgaben von <em>AUTOSAR_SWS_ExecutionManagement</em>. Ein daemon-basierter Functional Cluster muss zwingend nach erfolgreichem Start <code>ReportExecutionState(kRunning)</code> aufrufen, um State-Management-Timeouts und Fehlerreaktionen (z. B. Watchdog-Resets oder Neustart durch EM) zu verhindern.\n</li></ul>\n</li><li><strong>Stereotypisierung (<code>«aapAPI,aapNativeInterface»</code> vs. <code>«aapInternal»</code>):</strong>\n<ul class=\"fig-list\"><li><code>ExecutionClient</code> ist als native C++-API typisiert, die per IPC mit dem EM-Daemon kommuniziert und standardisiert ist (<code>ara::exec::ExecutionClient</code>).\n</li><li>Im Gegensatz dazu bleibt die Anbindung an den <code>TCP/IP Stack</code> als <code>«aapInternal»</code> eingestuft; sie unterliegt keinem AUTOSAR-weiten Standard, sondern verlangt OS-spezifische Kernel- oder Driver-Bindings (z. B. Netfilter/nftables unter Linux).\n</li></ul>\n</li><li><strong>Robustheit &amp; Threading-Vorgaben:</strong>\n<ul class=\"fig-list\"><li>Aufrufe von <code>ReportEvent()</code> und <code>ReportExecutionState()</code> dürfen die zeitkritische Paketverarbeitung im Netzwerk-Stack nicht blockieren; Entkopplung über asynchrone Queues/Worker-Threads ist architekturell vorzusehen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-905330d836bc8963", "to": "FIG-fce928ed410bb213", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Functional Cluster: Umbenennung von <code>Adaptive Intrusion Detection System Manager</code> in <code>Intrusion Detection System Manager</code> (Entfall des Präfixes <code>Adaptive</code>).\n</li></ul>"}, {"from": "FIG-fce928ed410bb213", "to": "FIG-32bda29d3b576cb0", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-32bda29d3b576cb0", "to": "FIG-237713263eec7842", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Functional Cluster: Neuer Cluster <code>«aapFunctionalCluster» Execution Management (daemon-based)</code> hinzugefügt.\n</li><li>Schnittstelle: Neue Schnittstelle <code>«aapAPI,aapNativeInterface» ExecutionClient</code> mit den Operationen <code>+ Create()</code> und <code>+ ReportExecutionState(ExecutionState)</code> ergänzt.\n</li><li>Abhängigkeiten: Neue <code>«use»</code>-Beziehung von <code>Firewall</code> auf <code>ExecutionClient</code>.\n</li><li>Realisierung: Neue Realisierungsbeziehung von <code>Execution Management</code> zu <code>ExecutionClient</code>.\n</li></ul>"}]};
